// ?init@InGameUI@@UAEXXZ
// partial score=0.6 date=2026-09-27
// Attempt body for ?init@InGameUI@@UAEXXZ @ 0x00440B40, 1091 bytes.
//
// IDENTITY IS SETTLED AND IS NOT createReplayControl.  The lift's name is
// wrong; the body is InGameUI::init:
//   * inputs/reference/shims/sweep/Common/SubsystemInterface.h:10 records the
//     retail SubsystemInterface vtable as "0 ~SubsystemInterface 1 init
//     2 loadIniFilesFromLegend 4 reset 5 update", so slot 1 is init.
//   * game/GameEngine/Source/Common/System/subsystem_interface.h:10 says the
//     same ("1 init 2 loadIniFilesFromLegend 4 reset 5 update").
//   * InGameUI's vtable 0x010F5B38 (installed by ctor 0x0044B800) slot 1
//     (+0x004) is the ILT thunk 0x00425027, and
//     game/gen_small/thunks_017.cpp:816 is `void j_00025027() { b_00440b40(); }`
//     -- that thunk routes to 0x00440B40.
//   * The body then does exactly InGameUI::init: the INI subsystem load, the
//     eight TheGlobalLanguageData font triples, the tactical view, the inlined
//     createControlBar and createReplayControl, new ControlBar, and
//     m_windowLayouts.clear().
//
// The real C++ body is InGameUI.cpp's InGameUI::init, which this attempt
// advanced from 635 to 173 non-reloc byte diffs.  The two corrections below
// are the whole of this attempt's gain and are already applied in place at
// game/GameEngine/Source/GameClient/InGameUI.cpp; they are reproduced here
// because they are the reusable part.

// ---------------------------------------------------------------------------
// CORRECTION 1 (the big one, 635 -> 173 diffs): read the global, do not hoist
// it.  Retail re-loads TheGlobalLanguageData into eax before EVERY field
// reference, including three consecutive loads with no intervening call:
//
//   +005c mov eax, [0x12f1484]
//   +0061 mov ecx, [eax + 0x98]        ; pointSize
//   +0067 mov [esi + 0x7c8], ecx        ; store through `this`
//   +006d mov edx, [0x12f1484]         ; reload, forced by that store
//   +0073 mov al, [edx + 0x9c]         ; bold
//   +0079 mov [esi + 0x7cc], al        ; store through `this`
//   +007f mov eax, [0x12f1484]         ; reload again
//
// That is MSVC 7.1 refusing to keep the global in a register across a store
// through `this`, which it cannot prove does not alias it.  A local copy of the
// pointer (the previous spelling) makes the compiler cache it in edi and emit
// none of the reloads.  Spelling the cast per use is what produces them.
// ---------------------------------------------------------------------------
struct BfmeInGameUIInitFont
{
	const char *name;
	Int pointSize;
	Bool bold;
};

struct BfmeGlobalLanguageInitView
{
	UnsignedByte pad0[0x34];
	BfmeInGameUIInitFont message;              // +0x34
	BfmeInGameUIInitFont militaryCaptionTitle; // +0x40
	BfmeInGameUIInitFont militaryCaption;      // +0x4c
	UnsignedByte pad1[0x0c];
	BfmeInGameUIInitFont superweaponNormal;    // +0x64
	BfmeInGameUIInitFont superweaponReady;     // +0x70
	BfmeInGameUIInitFont namedTimerNormal;     // +0x7c
	BfmeInGameUIInitFont namedTimerReady;      // +0x88
	BfmeInGameUIInitFont drawableCaption;      // +0x94
};

// CORRECTION 2: militaryCaption sits at this+0x884, immediately after
// militaryCaptionTitle at this+0x878.  The struct carried a spurious
// `UnsignedByte pad5[4]` that pushed it to 0x888.
struct BfmeInGameUIInitView
{
	UnsignedByte pad0[0x758];
	BfmeInGameUIInitFont superweaponNormal;        // +0x758
	BfmeInGameUIInitFont superweaponReady;         // +0x764
	UnsignedByte pad1[0x34];
	BfmeInGameUIInitFont namedTimerNormal;         // +0x7a4
	Int namedTimerNormalColor;                     // +0x7b0
	BfmeInGameUIInitFont namedTimerReady;          // +0x7b4
	UnsignedByte pad2[4];
	BfmeInGameUIInitFont drawableCaption;          // +0x7c4
	UnsignedByte pad3[0x7c];
	BfmeInGameUIInitFont message;                  // +0x84c
	UnsignedByte pad4[0x20];
	BfmeInGameUIInitFont militaryCaptionTitle;     // +0x878
	BfmeInGameUIInitFont militaryCaption;          // +0x884
};

// The global is re-read at every field reference, not hoisted into a local:
// retail reloads it after each store through `this`, because it cannot prove
// the two do not alias.  Spelling the cast per use is what makes MSVC do that.
#define BFME_INIT_LANG ((const BfmeGlobalLanguageInitView *)TheGlobalLanguageData)
#define BFME_INIT_UI ((BfmeInGameUIInitView *)this)

#define BFME_COPY_INIT_FONT(destination, source) \
	do { \
		const char *nameData = (source).name; \
		if (nameData && *reinterpret_cast<const unsigned short *>(nameData + 4)) \
		{ \
			reinterpret_cast<AsciiString &>((destination).name) = \
				reinterpret_cast<const AsciiString &>((source).name); \
			(destination).pointSize = (source).pointSize; \
			(destination).bold = (source).bold; \
		} \
	} while (0)

	//override INI values with language localized values:
	if (TheGlobalLanguageData)
	{
		BFME_COPY_INIT_FONT(BFME_INIT_UI->drawableCaption, BFME_INIT_LANG->drawableCaption);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->message, BFME_INIT_LANG->message);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->militaryCaptionTitle, BFME_INIT_LANG->militaryCaptionTitle);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->militaryCaption, BFME_INIT_LANG->militaryCaption);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->superweaponNormal, BFME_INIT_LANG->superweaponNormal);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->superweaponReady, BFME_INIT_LANG->superweaponReady);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->namedTimerNormal, BFME_INIT_LANG->namedTimerNormal);
		BFME_COPY_INIT_FONT(BFME_INIT_UI->namedTimerReady, BFME_INIT_LANG->namedTimerReady);
	}

// ---------------------------------------------------------------------------
// RESIDUAL, measured with tools/probe.py after the two corrections above:
//   size   ours=972 retail=1091   diffs 173 non-reloc bytes
//   shape  0.841 of instructions match after normalising registers/constants
//   first divergence at byte 602 (0x25a), the createView call; bytes 0..601
//   match retail exactly.
//
// Everything left needs a SHARED class layout corrected, which is a full-gate
// edit with a wide blast radius, so it was not done here.  Each row is a
// virtual call whose retail slot is past the slot the Zero Hour class layout
// in this tree compiles against:
//
//   site            retail slot   ours     class    shortfall
//   createView      108 (+0x1b0)  104       InGameUI   4
//   (slot 109)      109 (+0x1b4)   --       InGameUI   4
//   attachView       28 (+0x70)    20       Display    8
//   Display::getWidth 11 (+0x2c)   8       Display    3
//   Display::getHeight 12 (+0x30)  9       Display    3
//   View::setWidth   14 (+0x38)   12       View       2
//   View::setHeight  16 (+0x40)   14       View       2
//   View::setDefaultView 56(+0xe0) 51       View       5
//
// The InGameUI figure is a property of the ZH GeneralsMD InGameUI.h this TU
// compiles against (inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/
// GameEngine/Include/GameClient/InGameUI.h, per the .deps.json of the probe).
// It is four virtuals short before createView, not a bad spelling: retail slots
// 108 and 109 of 0x010F5B38 are both ?rva0088C500PureVirtualReport, i.e. the
// pure virtuals createView and the slot after it.  The Display figure is a gap
// in inputs/reference/shims/sweep/GameClient/Display.h, whose own header note
// already claims "Display::getWidth stays at slot 11 / vtable+0x2c" while the
// declaration puts it at 8.
//
// A per-call-site workaround is possible but not worth banking: MSVC 7.1 will
// not subscript a pointer-to-__stdcall-function typedef (C2109 -- the
// parenthesised `typedef R (__stdcall *F)(C*)` form does compile), and even
// then it emits `push esi; call [esi+0x1b0]` where retail has
// `mov edx,[esi]; mov ecx,esi; call [edx+0x1b0]`.  Reproducing retail needs a
// real virtual, which means a 108-entry local vtable padder.  Fix the class
// layouts instead and all of this disappears.
//
// Three further items, all needing an identity this body does not prove:
//
// 1. The two AsciiString temporaries.  Retail calls the out-of-line
//    ??0BFMERetailAsciiString@@QAE@PBD@Z at 0x00888BC0 (aliased in the ledger
//    to ??0?$StringBase@D@@AAE@PBD@Z @ StringBase.cpp).  The shimmed
//    AsciiString(const char*) is inline and folds to
//    ?ensureUniqueBufferOfSize@AsciiString@@IAEXH_NPBD1@Z, so ours emits four
//    pushes where retail emits one, which also shifts the unwind slot from
//    [esp+0x14] to [esp+0x10].  Fix: the repo's usual TU-local
//    `class BFMERetailAsciiString { BFMERetailAsciiString(const char*); }`
//    (see game/GameEngine/Source/Common/BfmeConv1936.cpp:3), plus a TU-local
//    GameWindowManager view, since winCreateFromScript is vtable slot 26
//    (+0x68) and takes the string by value.
//
// 2. The tail BFME adds after m_windowLayouts.clear(), absent from the Zero
//    Hour source and from the current body.  In retail, from +0x396:
//      new(0x30) -> ctor 0x0042C985 -> global 0x012F4B78 -> call [vtable+0x4]
//      call [this vtable + 0x1b4]                (InGameUI slot 109, unnamed)
//      new(0x44) -> ctor 0x00434CF7 -> TheBannerUI 0x012F4B70
//                 -> call [vtable+0x4] -> call [vtable+0x8]
//    The last call is BannerUI vtable 0x0110B828 slot 2, which
//    tools/vtable_lookup.py resolves to
//    ?loadIniFilesFromLegend@SubsystemInterface@@UAE_NXZ.  Neither 0x42C985 nor
//    0x434CF7 has a ledger row, so their classes have no proven identity yet.
//
// 3. this+0x13A4 = 0 at the end.  tools/name_oracle.py --class InGameUI
//    --offset 0x13a4 says "not witnessed; ZH records no own member at that
//    offset either", while the ZH member m_soloNexusSelectedDrawableID sits at
//    +0x1d78.  So the InvalidDrawableID store needs a view with an
//    address-keyed member, the way the landed ?update@InGameUI@@UAEXXZ body
//    already reaches BFME offsets through BfmeUpdateLayout.
// ---------------------------------------------------------------------------
